import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.DCVnL8g5.js";const m=JSON.parse('{"title":"Introducción y arquitectura","description":"","frontmatter":{},"headers":[],"relativePath":"data-engineering/iceberg/01-introduccion-y-arquitectura.md","filePath":"data-engineering/iceberg/01-introduccion-y-arquitectura.md","lastUpdated":1789040978000,"isDraft":false}'),o={name:"data-engineering/iceberg/01-introduccion-y-arquitectura.md"};function r(i,a,l,c,p,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="introduccion-y-arquitectura" tabindex="-1">Introducción y arquitectura <a class="header-anchor" href="#introduccion-y-arquitectura" aria-label="Permalink to &quot;Introducción y arquitectura&quot;">​</a></h1><p>Apache Iceberg es un <strong>formato de tabla abierto</strong>: un protocolo de metadatos y commits que trata una colección de ficheros (Parquet, Avro u ORC) como una <strong>tabla lógica</strong>. No es Spark, ni un motor SQL, ni un catálogo, ni un servicio cloud, ni “Parquet con un candado”.</p><p>Documentación: <a href="https://iceberg.apache.org/" target="_blank" rel="noreferrer">iceberg.apache.org</a>, <a href="https://iceberg.apache.org/spec/" target="_blank" rel="noreferrer">especificación</a>, <a href="https://iceberg.apache.org/docs/latest/" target="_blank" rel="noreferrer">docs latest</a>, <a href="https://iceberg.apache.org/releases/" target="_blank" rel="noreferrer">releases</a>.</p><h2 id="el-problema-de-las-carpetas-de-parquet" tabindex="-1">El problema de las carpetas de Parquet <a class="header-anchor" href="#el-problema-de-las-carpetas-de-parquet" aria-label="Permalink to &quot;El problema de las carpetas de Parquet&quot;">​</a></h2><p>Un lago “solo directorios” deja que cada job liste <code>s3://…/events/dt=2026-09-08/</code> y decida qué es la tabla:</p><ul><li>un writer a medias deja lecturas inconsistentes;</li><li>no hay un <strong>estado de tabla</strong> único: el listing <em>es</em> la verdad;</li><li>cambiar el esquema o el particionado suele exigir una tabla nueva o reescribir todo;</li><li>varios motores no se ponen de acuerdo sobre qué ficheros están vivos.</li></ul><p>Iceberg no sustituye el object store. Añade un <strong>árbol de metadatos</strong> y un <strong>commit</strong> que publica, de forma atómica, <em>qué</em> ficheros pertenecen al snapshot actual. La tabla <strong>no</strong> se descubre listando el warehouse.</p><h2 id="jerarquia-no-la-confundas" tabindex="-1">Jerarquía (no la confundas) <a class="header-anchor" href="#jerarquia-no-la-confundas" aria-label="Permalink to &quot;Jerarquía (no la confundas)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>local.analytics.events</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>     catálogo          ← ¿cuál es el metadata.json actual?</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   metadata.json       ← esquema, specs, refs, snapshot current</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>     snapshot          ← una versión de la tabla</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  manifest list</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>    manifests</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> data files / delete files   (Parquet, Avro, ORC, …)</span></span></code></pre></div><p>Cada nivel tiene un trabajo distinto. El capítulo 2 baja al detalle; aquí basta con el modelo.</p><h2 id="catalogo-y-commit" tabindex="-1">Catálogo y commit <a class="header-anchor" href="#catalogo-y-commit" aria-label="Permalink to &quot;Catálogo y commit&quot;">​</a></h2><p>El <strong>catálogo</strong> no guarda las filas. Localiza y <strong>cambia el puntero</strong> al metadata vigente:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>metadata v12</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>writer crea metadata v13 (ficheros nuevos + metadatos)</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>commit atómico en el catálogo:</span></span>
<span class="line"><span>puntero v12 → v13</span></span></code></pre></div><p>Si otro writer commitea antes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>conflicto</span></span>
<span class="line"><span>→ refresh (leer el metadata actual)</span></span>
<span class="line"><span>→ validar si el cambio sigue siendo aplicable</span></span>
<span class="line"><span>→ retry cuando sea seguro</span></span></code></pre></div><p>Eso es <strong>optimistic concurrency</strong>. No hay un lock universal de fila ni un mecanismo único de “rename de ficheros” en todos los storages: la atomicidad del puntero depende del <strong>catálogo</strong> (capítulo 6).</p><h2 id="snapshots-no-copias-fisicas" tabindex="-1">Snapshots, no copias físicas <a class="header-anchor" href="#snapshots-no-copias-fisicas" aria-label="Permalink to &quot;Snapshots, no copias físicas&quot;">​</a></h2><p>Cada commit produce normalmente un <strong>snapshot</strong> nuevo: un ID, un padre, un timestamp y una operación (<code>append</code>, <code>overwrite</code>, <code>delete</code>, …). Un lector fija un snapshot y ve un conjunto coherente de ficheros. Time travel es leer otro snapshot, no clonar el bucket.</p><p>Los snapshots se <strong>expiran</strong>. No son un backup.</p><h2 id="lo-que-iceberg-habilita-recorrido" tabindex="-1">Lo que Iceberg habilita (recorrido) <a class="header-anchor" href="#lo-que-iceberg-habilita-recorrido" aria-label="Permalink to &quot;Lo que Iceberg habilita (recorrido)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capacidad</th><th>Dónde se desarrolla</th></tr></thead><tbody><tr><td>Árbol metadata / manifests</td><td><a href="./02-tablas-snapshots-y-manifests">capítulo 2</a></td></tr><tr><td>Hidden partitioning y evolución de specs</td><td><a href="./03-particionado-oculto">capítulo 3</a></td></tr><tr><td>Evolución de esquema por <strong>column IDs</strong></td><td><a href="./04-evolucion-de-esquema">capítulo 4</a></td></tr><tr><td>Lectura/escritura con Spark</td><td><a href="./05-lectura-y-escritura-con-spark">capítulo 5</a></td></tr><tr><td>Hadoop / Hive / REST / JDBC</td><td><a href="./06-catalogos">capítulo 6</a></td></tr><tr><td>Compaction, manifests, expire, orphans</td><td><a href="./07-optimizacion">capítulo 7</a></td></tr></tbody></table><h2 id="multi-engine" tabindex="-1">Multi-engine <a class="header-anchor" href="#multi-engine" aria-label="Permalink to &quot;Multi-engine&quot;">​</a></h2><p>Spark es el motor <strong>pedagógico</strong> de este manual: la documentación oficial lo trata como el más completo hoy. Iceberg también tiene conectores para Flink, Trino, Presto, Hive y otros. <strong>No</strong> hay paridad de features: un <code>MERGE</code> que funciona en Spark no implica el mismo soporte en Trino o Flink. Lo que sí comparte un motor compatible es la spec, el catálogo y las <em>features</em> que la tabla ya activó.</p><p>Delta Lake resuelve un problema parecido (tabla lakehouse sobre un lago) con <strong>otro</strong> árbol de metadatos y otro ecosistema. Este manual no es una comparativa.</p><h2 id="spec" tabindex="-1">Spec <a class="header-anchor" href="#spec" aria-label="Permalink to &quot;Spec&quot;">​</a></h2><p>La spec <strong>v1, v2 y v3</strong> están adoptadas. La <strong>v4 está en desarrollo</strong> y no está formalmente adoptada: no la uses como formato de producción. Subir <code>format-version</code> puede añadir capacidades que un lector antiguo no entiende. Más nuevo no es automáticamente mejor.</p><p>Siguiente: <a href="./02-tablas-snapshots-y-manifests">Tablas, snapshots y manifests</a>.</p>`,27)])])}const h=e(o,[["render",r]]);export{m as __pageData,h as default};
